files.content:
.root {
  --vt-surface: #ffffff;
  --vt-surface-2: #f9f9f9;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #ffffff;
  --vt-accent: #247cff;
  --vt-on-accent: #ffffff;
  --vt-accent-ink: #1a5bbf;
  --vt-accent-on-deep: #6ea8ff;
  --vt-line: #eaeaea;

  font-family: 'Open Sans', sans-serif;
  background: var(--vt-surface);
  color: var(--vt-ink);
  line-height: 1.5;
}

.root a {
  color: var(--vt-ink-soft);
  text-decoration: none;
  transition: all 0.3s;
}

.root a:hover {
  color: var(--vt-accent);
}

.root h1,
.root h2,
.root h3,
.root h4,
.root h5,
.root h6 {
  color: var(--vt-ink);
  line-height: inherit;
  font-weight: 600;
}

.root h1,
.root h2 {
  font-weight: 700;
}

.root h1 {
  font-size: 48px;
  line-height: normal;
}

.root h2 {
  font-size: 36px;
}

.root h3 {
  font-size: 32px;
}

.root h4 {
  font-size: 28px;
}

.root h5 {
  font-size: 24px;
}

.root h6 {
  font-size: 22px;
}

.root p {
  color: var(--vt-ink-soft);
  font-size: 18px;
  font-weight: 300;
  letter-spacing: 0.5px;
}

.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: var(--vt-surface);
  box-shadow: 0 0.125rem 0.25rem color-mix(in srgb, var(--vt-ink) 10%, transparent);
  padding: 20px 0;
}

.navIn {
  max-width: 1140px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 15px;
}

.logo {
  display: block;
  text-decoration: none;
  color: var(--vt-accent);
  font-size: 24px;
  font-weight: 700;
}

.navLinks {
  display: flex;
  gap: 30px;
}

.navLinks a {
  color: var(--vt-ink-soft);
  font-weight: 600;
  font-size: 16px;
  padding: 15px 0;
}

.navLinks a:hover {
  color: var(--vt-ink);
}

.hero {
  position: relative;
  padding-top: 94px;
  background: var(--vt-surface);
}

.heroTrack {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
}

.heroSlide {
  flex: 0 0 100%;
  scroll-snap-align: start;
}

.heroSlide img {
  width: 100%;
  height: 580px;
  object-fit: cover;
  display: block;
}

.heroCard {
  position: absolute;
  bottom: 0;
  right: 0;
  background: var(--vt-surface);
  padding: 1.5rem 2.5rem;
  width: 50%;
  z-index: 2;
  box-shadow: 0 0.5rem 1rem color-mix(in srgb, var(--vt-ink) 15%, transparent);
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.heroCard h1 {
  font-size: 48px;
  margin-bottom: 0.5rem;
  color: var(--vt-ink);
}

.heroCard p {
  margin-bottom: 1rem;
}

.heroLinks {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
}

.customLink {
  display: inline-block;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent-ink);
  font-weight: 600;
  line-height: 40px;
  padding: 0 30px;
  text-transform: uppercase;
  text-decoration: none;
  margin-right: 1rem;
  transition: all 0.3s;
}

.customLink:hover {
  color: var(--vt-accent-ink);
  background: var(--vt-line);
}

.contactPhone {
  font-weight: 600;
  color: var(--vt-ink);
  display: flex;
  align-items: center;
}

.phoneIcon::before {
  content: "\260E";
  color: var(--vt-accent-ink);
  margin-right: 8px;
  font-style: normal;
}

.sectionPadding {
  padding-top: 7rem;
  padding-bottom: 7rem;
}

.container {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
}

.about {
  background: var(--vt-surface-2);
}

.aboutRow {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
}

.aboutText {
  flex: 0 0 50%;
}

.aboutText h2 {
  margin-bottom: 1rem;
}

.gallery {
  background: var(--vt-surface);
}

.galleryRow {
  display: flex;
  flex-wrap: wrap;
}

.galleryItem {
  flex: 0 0 50%;
  padding: 0;
}

.galleryItem img {
  width: 100%;
  height: auto;
  display: block;
}

.timelineSection {
  background: var(--vt-surface-2);
}

.timelineHeading {
  text-align: center;
  margin-bottom: 3rem;
  color: var(--vt-ink);
}

.timeline {
  position: relative;
  padding: 20px 0;
}

.timeline::before {
  content: "";
  position: absolute;
  top: 37px;
  left: 50%;
  width: 0;
  border-left: 1px solid var(--vt-line);
  height: 85%;
  transform: translateX(-50%);
  z-index: 1;
}

.timelineNode {
  display: flex;
  align-items: flex-start;
  position: relative;
  margin-bottom: 2rem;
}

.timelineContent {
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem color-mix(in srgb, var(--vt-ink) 15%, transparent);
  border-radius: 0 0 0.25rem 0.25rem;
  position: relative;
  width: 50%;
}

.timelineNode:nth-child(odd) .timelineContent {
  margin-right: 5%;
}

.timelineNode:nth-child(even) .timelineContent {
  margin-left: 5%;
}

.timelineContent h3 {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 10px 30px;
  border-radius: 0.25rem 0.25rem 0 0;
  position: relative;
}

.timelineContent p {
  padding: 10px 30px;
  color: var(--vt-ink-soft);
}

.timelineNode:nth-child(odd) .timelineContent h3::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 100%;
  transform: translateY(-50%);
  border-left: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineNode:nth-child(even) .timelineContent h3::after {
  content: "";
  position: absolute;
  top: 50%;
  right: 100%;
  transform: translateY(-50%);
  border-right: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineIcon {
  position: relative;
  z-index: 100;
  flex: 0 0 auto;
  margin: 0 20px;
}

.timelineIcon span {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: var(--vt-surface);
  box-shadow: 0 1rem 3rem color-mix(in srgb, var(--vt-ink) 15%, transparent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 32px;
  color: var(--vt-accent-ink);
  line-height: 80px;
}

.timelineDate {
  width: 30%;
  padding-top: 40px;
}

.timelineNode:nth-child(odd) .timelineDate {
  text-align: left;
}

.timelineNode:nth-child(even) .timelineDate {
  text-align: right;
}

.timelineDate time {
  color: var(--vt-ink-soft);
  font-weight: 300;
}

.siteFooter {
  background: var(--vt-surface-2);
  padding-top: 7rem;
  padding-bottom: 7rem;
}

.footerRow {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
}

.footerCol1 {
  flex: 0 0 41.6667%;
}

.footerCol2 {
  flex: 0 0 16.6667%;
}

.footerCol3 {
  flex: 0 0 25%;
}

.footerCol1 h5,
.footerCol2 h5,
.footerCol3 h5 {
  margin-bottom: 1.5rem;
}

.footerCol1 p,
.footerCol2 p {
  color: var(--vt-ink-soft);
}

.socialLinks {
  display: flex;
  gap: 15px;
  list-style: none;
  padding: 0;
  margin: 0;
}

.socialLinks a {
  color: var(--vt-ink-soft);
}

.socialLinks a:hover {
  color: var(--vt-accent);
}

.copyright {
  margin-top: 3rem;
  text-align: left;
}

.copyright p {
  font-size: 16px;
  color: var(--vt-ink-soft);
}

@media screen and (max-width: 991px) {
  .heroSlide img {
    height: auto;
  }

  .heroCard {
    position: relative;
    bottom: 100px;
    left: 0;
    width: auto;
    margin-bottom: -100px;
    padding: 2rem;
  }

  .aboutText {
    flex: 0 0 100%;
  }
}

@media screen and (max-width: 767px) {
  .timeline::before {
    left: 33px;
    top: 60px;
  }

  .timelineNode {
    flex-direction: column;
    align-items: flex-start;
    margin-left: 50px;
  }

  .timelineContent {
    width: 100%;
  }

  .timelineNode:nth-child(odd) .timelineContent,
  .timelineNode:nth-child(even) .timelineContent {
    margin: 0;
  }

  .timelineIcon {
    position: absolute;
    left: 0;
    top: 60px;
  }
}

@media screen and (max-width: 575px) {
  .timeline::before {
    left: 57px;
  }

  .timelineIcon {
    left: -10px;
  }
}

@media screen and (max-width: 480px) {
  .heroLinks .customLink {
    font-size: 12px;
    line-height: 30px;
    padding: 0 25px;
    margin-right: 12px;
  }

  .contactPhone {
    font-size: 12px;
  }
}

@media screen and (max-width: 360px) {
  .timelineIcon span {
    width: 70px;
    height: 70px;
    line-height: 70px;
  }
}
